insert into public.cards (id, numero, nom, categorie, rarete, icone, description, info, le_savais_tu, a_retenir, obtention, nature, sources, verif_statut, publie) values
  ('triangle-du-feu', 1, 'Triangle du feu', 'incendie', 'commune', 'Triangle', 'Un feu ne peut naître que si trois éléments sont réunis : un combustible, un comburant (le plus souvent l’oxygène de l’air) et une source d’énergie (chaleur, étincelle).', 'Tous les moyens d’extinction agissent en supprimant au moins un des trois côtés du triangle : refroidir, étouffer ou retirer le combustible.', 'Un simple court-circuit, une surface chaude ou une étincelle de meulage suffisent à fournir l’énergie d’activation.', 'Éloigner les combustibles des sources de chaleur, c’est déjà prévenir l’incendie.', '{"type":"maitrise","seuil":1}'::jsonb, 'recommandation', '[{"label":"INRS : Incendie et explosion","url":"https://www.inrs.fr/risques/incendie-explosion.html"}]'::jsonb, 'a-verifier', true),
  ('alarme-incendie', 2, 'Alarme incendie', 'incendie', 'commune', 'Siren', 'Le signal sonore d’alarme générale ordonne l’évacuation. Chacun doit savoir le reconnaître et le distinguer des autres signaux du site.', 'Les établissements où plus de cinquante personnes peuvent être réunies, ou qui manipulent des matières inflammables, doivent disposer d’un système d’alarme sonore.', 'Les exercices d’évacuation servent notamment à apprendre à reconnaître le son de l’alarme générale.', 'Dès que l’alarme retentit, on évacue : on n’attend pas de savoir si c’est un exercice.', '{"type":"maitrise","seuil":3}'::jsonb, 'obligation', '[{"label":"Code du travail, art. R4227-34","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"INRS : Incendie et explosion","url":"https://www.inrs.fr/risques/incendie-explosion.html"}]'::jsonb, 'a-verifier', true),
  ('classes-de-feu', 3, 'Classes de feu', 'incendie', 'peu-commune', 'Layers', 'Les feux sont classés selon la nature du combustible : A (solides), B (liquides ou solides liquéfiables), C (gaz), D (métaux) et F (huiles et graisses de cuisson).', 'La classe de feu indiquée sur un extincteur précise sur quels feux il est efficace. Un extincteur inadapté peut être inefficace, voire aggraver la situation.', 'Il n’existe plus de « classe E » pour les feux d’origine électrique : on vérifie sur l’extincteur la mention d’utilisation sur les équipements sous tension.', 'Avant d’utiliser un extincteur, lire son étiquette : classes de feu et usage électrique.', '{"type":"maitrise","seuil":5}'::jsonb, 'norme', '[{"label":"Norme NF EN 2 (classification des feux)"},{"label":"INRS : Incendie et explosion","url":"https://www.inrs.fr/risques/incendie-explosion.html"}]'::jsonb, 'a-verifier', true),
  ('extincteur-co2', 4, 'Extincteur CO2', 'incendie', 'rare', 'FireExtinguisher', 'L’extincteur au dioxyde de carbone est adapté aux feux d’origine électrique et à certains feux de liquides inflammables. Il étouffe le feu sans laisser de résidu.', 'Le CO2 sort très froid : le diffuseur peut provoquer des brûlures par le froid. Dans un local exigu, le gaz chasse l’oxygène : il faut aérer après usage.', 'Le CO2 est peu efficace sur les feux de solides qui forment des braises (bois, papier) : le feu peut reprendre une fois le gaz dissipé.', 'Tenir l’extincteur CO2 par la poignée, jamais par le diffuseur, et ne pas l’utiliser sur une personne.', '{"type":"parcours","parcoursId":"p-incendie"}'::jsonb, 'recommandation', '[{"label":"INRS : Incendie et explosion","url":"https://www.inrs.fr/risques/incendie-explosion.html"}]'::jsonb, 'a-verifier', true),
  ('evacuation', 5, 'Procédure d’évacuation', 'incendie', 'epique', 'DoorOpen', 'Une consigne de sécurité incendie, affichée dans l’établissement, précise l’organisation de l’évacuation. Des exercices ont lieu au moins tous les six mois.', 'On suit le balisage vers la sortie, on n’utilise pas les ascenseurs, on referme les portes derrière soi sans les verrouiller et on rejoint le point de rassemblement.', 'En présence de fumée, l’air respirable se trouve près du sol : on se baisse pour progresser.', 'Au point de rassemblement, on se signale et on ne retourne jamais chercher un objet.', '{"type":"scenario","scenarioId":"s-incendie"}'::jsonb, 'obligation', '[{"label":"Code du travail, art. R4227-37 à R4227-39","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"INRS : Incendie et explosion","url":"https://www.inrs.fr/risques/incendie-explosion.html"}]'::jsonb, 'a-verifier', true),
  ('serre-file', 6, 'Guide-file et serre-file', 'incendie', 'legendaire', 'Flag', 'Le guide-file ouvre la marche vers la sortie. Le serre-file ferme la marche et vérifie que personne ne reste dans la zone : bureaux, sanitaires, salles de réunion.', 'Ces rôles sont désignés par l’entreprise dans son organisation de l’évacuation. Ils rendent compte au responsable de l’évacuation au point de rassemblement.', 'Le serre-file referme les portes derrière lui pour ralentir la propagation des fumées.', 'Connaître les guide-files et serre-files de sa zone, et suivre leurs consignes.', '{"type":"collection"}'::jsonb, 'recommandation', '[{"label":"INRS : Incendie et explosion","url":"https://www.inrs.fr/risques/incendie-explosion.html"}]'::jsonb, 'a-verifier', true),
  ('casque', 7, 'Casque de protection', 'epi', 'commune', 'HardHat', 'Le casque protège la tête contre les chutes d’objets et les chocs. Il est obligatoire dans les zones où ce risque est signalé.', 'Un casque a une durée d’utilisation fixée par le fabricant. Il doit être remplacé après un choc important, même sans dommage visible.', 'Le harnais intérieur, qui laisse un espace entre la coque et la tête, absorbe une grande partie de l’énergie du choc.', 'Un casque se règle à sa tête, se porte jugulaire attachée si nécessaire et se remplace après un choc.', '{"type":"maitrise","seuil":1}'::jsonb, 'norme', '[{"label":"Norme EN 397 (casques de protection pour l’industrie)"},{"label":"INRS : Équipements de protection individuelle","url":"https://www.inrs.fr/demarche/equipements-protection-individuelle.html"}]'::jsonb, 'a-verifier', true),
  ('lunettes', 8, 'Lunettes de protection', 'epi', 'commune', 'Glasses', 'Lunettes, lunettes-masques ou écrans faciaux protègent les yeux des projections, poussières, produits chimiques et rayonnements.', 'Le modèle dépend du risque : lunettes à branches pour les projections légères, lunettes-masques contre les liquides, filtres spécifiques pour le soudage.', 'Des lunettes de vue ne sont pas des lunettes de protection : il existe des surlunettes et des modèles correcteurs certifiés.', 'Choisir la protection oculaire selon le risque, pas selon le confort.', '{"type":"maitrise","seuil":3}'::jsonb, 'norme', '[{"label":"Norme EN 166 (protection individuelle de l’œil)"},{"label":"INRS : Équipements de protection individuelle","url":"https://www.inrs.fr/demarche/equipements-protection-individuelle.html"}]'::jsonb, 'a-verifier', true),
  ('protection-auditive', 9, 'Protection auditive', 'epi', 'peu-commune', 'Ear', 'Bouchons et casques antibruit réduisent l’exposition sonore. À partir de 80 dB(A) sur 8 heures, l’employeur met des protecteurs à disposition ; à partir de 85 dB(A), il veille à ce qu’ils soient portés.', 'La valeur limite d’exposition est de 87 dB(A), en tenant compte de l’atténuation apportée par les protecteurs.', 'La perte d’audition due au bruit est irréversible et s’installe sans douleur.', 'Dans une zone bruyante, on porte ses protections en permanence : les retirer quelques minutes suffit à réduire fortement leur efficacité.', '{"type":"maitrise","seuil":5}'::jsonb, 'obligation', '[{"label":"Code du travail, art. R4431-2 et R4434-7","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"INRS : Bruit","url":"https://www.inrs.fr/risques/bruit.html"}]'::jsonb, 'a-verifier', true),
  ('gants', 10, 'Gants adaptés', 'epi', 'rare', 'Hand', 'Il n’existe pas de gant universel : risques mécaniques (coupures, abrasion), chimiques et thermiques demandent chacun des gants spécifiques.', 'Les pictogrammes et codes inscrits sur le gant indiquent ses performances. Un gant de manutention ne protège pas d’un produit chimique.', 'Près d’une machine avec des pièces en rotation, porter des gants peut augmenter le risque d’entraînement de la main.', 'Vérifier que le gant correspond au risque et l’inspecter avant chaque utilisation.', '{"type":"parcours","parcoursId":"p-epi"}'::jsonb, 'norme', '[{"label":"Norme EN 388 (risques mécaniques), EN ISO 374 (risques chimiques)"},{"label":"INRS : Équipements de protection individuelle","url":"https://www.inrs.fr/demarche/equipements-protection-individuelle.html"}]'::jsonb, 'a-verifier', true),
  ('chaussures', 11, 'Chaussures de sécurité', 'epi', 'epique', 'Footprints', 'Les chaussures de sécurité possèdent un embout protégeant les orteils contre l’écrasement. Selon leur classe, elles offrent aussi une semelle antiperforation ou une résistance à l’eau.', 'Le marquage (SB, S1, S2, S3…) indique les protections présentes. On choisit la classe selon les risques du poste.', 'L’embout d’une chaussure de sécurité est testé pour résister à un choc de 200 joules.', 'Des chaussures de sécurité abîmées ou déformées ne protègent plus : on les remplace.', '{"type":"scenario","scenarioId":"s-epi"}'::jsonb, 'norme', '[{"label":"Norme EN ISO 20345 (chaussures de sécurité)"},{"label":"INRS : Équipements de protection individuelle","url":"https://www.inrs.fr/demarche/equipements-protection-individuelle.html"}]'::jsonb, 'a-verifier', true),
  ('protection-collective', 12, 'Protection collective d’abord', 'epi', 'legendaire', 'ShieldCheck', 'Parmi les principes généraux de prévention, l’employeur doit donner la priorité aux mesures de protection collective sur les mesures de protection individuelle.', 'L’EPI intervient quand le risque ne peut pas être évité ou suffisamment limité autrement. Il est fourni gratuitement par l’employeur.', 'Le Code du travail énumère neuf principes généraux de prévention, du plus efficace (éviter le risque) au moins efficace.', 'L’EPI est le dernier rempart : il complète les protections collectives, il ne les remplace pas.', '{"type":"collection"}'::jsonb, 'obligation', '[{"label":"Code du travail, art. L4121-2 et R4323-95","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"INRS : Équipements de protection individuelle","url":"https://www.inrs.fr/demarche/equipements-protection-individuelle.html"}]'::jsonb, 'a-verifier', true),
  ('risque-electrique', 13, 'Risque électrique', 'risques', 'commune', 'Zap', 'Le courant électrique peut provoquer électrisation, électrocution, brûlures et incendies. Les opérations sur les installations électriques sont réservées aux personnes habilitées.', 'L’habilitation électrique est délivrée par l’employeur après une formation. Elle précise ce que la personne est autorisée à faire.', 'Un équipement hors tension n’est pas forcément sans danger : certains éléments, comme les condensateurs, peuvent rester chargés.', 'Sans habilitation, on n’ouvre pas une armoire électrique et on ne répare pas un câble : on signale.', '{"type":"maitrise","seuil":1}'::jsonb, 'obligation', '[{"label":"Code du travail, art. R4544-9","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"Norme NF C 18-510"},{"label":"INRS : Risques électriques","url":"https://www.inrs.fr/risques/electriques.html"}]'::jsonb, 'a-verifier', true),
  ('pictogrammes-chimiques', 14, 'Pictogrammes de danger', 'risques', 'commune', 'FlaskConical', 'Les produits chimiques dangereux portent des pictogrammes en forme de losange blanc bordé de rouge : inflammable, toxique, corrosif, dangereux pour la santé, etc.', 'L’étiquette indique aussi une mention d’avertissement (« Danger » ou « Attention ») et des conseils de prudence.', 'Le règlement européen CLP définit neuf pictogrammes de danger.', 'On lit l’étiquette avant d’utiliser un produit, et on ne le transvase jamais dans un contenant alimentaire.', '{"type":"maitrise","seuil":3}'::jsonb, 'obligation', '[{"label":"Règlement (CE) n° 1272/2008 (CLP)","url":"https://eur-lex.europa.eu/eli/reg/2008/1272/oj"},{"label":"INRS : Risques chimiques","url":"https://www.inrs.fr/risques/chimiques.html"}]'::jsonb, 'a-verifier', true),
  ('fds', 15, 'Fiche de données de sécurité', 'risques', 'peu-commune', 'FileText', 'La fiche de données de sécurité (FDS) accompagne les produits chimiques dangereux. Elle décrit leurs dangers, les précautions d’emploi et la conduite à tenir en cas d’accident.', 'Le fournisseur doit la transmettre. Elle comporte 16 rubriques normalisées, dont les premiers secours, la lutte contre l’incendie et les EPI recommandés.', 'La rubrique 8 de la FDS précise les équipements de protection individuelle adaptés au produit.', 'Savoir où sont rangées les FDS des produits utilisés dans son service.', '{"type":"maitrise","seuil":5}'::jsonb, 'obligation', '[{"label":"Règlement (CE) n° 1907/2006 (REACH), art. 31","url":"https://eur-lex.europa.eu/eli/reg/2006/1907/oj"},{"label":"INRS : Risques chimiques","url":"https://www.inrs.fr/risques/chimiques.html"}]'::jsonb, 'a-verifier', true),
  ('chute-hauteur', 16, 'Chute de hauteur', 'risques', 'rare', 'ArrowDownToLine', 'Les chutes de hauteur figurent parmi les principales causes d’accidents graves au travail. Elles peuvent survenir même à faible hauteur.', 'La protection collective (garde-corps, plateforme) est prioritaire. L’échelle n’est pas un poste de travail, sauf impossibilité technique ou travaux de courte durée à faible risque.', 'Un escabeau ou une chaise utilisés pour atteindre une étagère sont à l’origine de nombreuses chutes en bureau.', 'Pour travailler en hauteur, on utilise un équipement adapté (plateforme individuelle roulante), jamais une chaise.', '{"type":"parcours","parcoursId":"p-risques"}'::jsonb, 'obligation', '[{"label":"Code du travail, art. R4323-63","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"INRS : Chutes de hauteur","url":"https://www.inrs.fr/risques/chutes-hauteur.html"}]'::jsonb, 'a-verifier', true),
  ('consignation', 17, 'Consignation des machines', 'risques', 'epique', 'Lock', 'Avant une intervention (maintenance, nettoyage, déblocage), une machine est mise en sécurité : séparation des énergies, condamnation, vérification de l’absence d’énergie.', 'La condamnation (cadenas personnel, étiquette) empêche une remise en marche pendant que quelqu’un intervient.', 'Couper une machine par son bouton d’arrêt ne suffit pas : de l’énergie peut subsister (pression, ressort, inertie).', 'On ne neutralise jamais un protecteur ou un dispositif de sécurité d’une machine.', '{"type":"scenario","scenarioId":"s-risques"}'::jsonb, 'recommandation', '[{"label":"INRS : Machines","url":"https://www.inrs.fr/risques/machines.html"}]'::jsonb, 'a-verifier', true),
  ('duerp', 18, 'Document unique (DUERP)', 'risques', 'legendaire', 'BookMarked', 'L’employeur évalue les risques professionnels et transcrit les résultats dans le document unique d’évaluation des risques professionnels (DUERP).', 'Dans les entreprises d’au moins 11 salariés, le document unique est mis à jour au moins chaque année, ainsi qu’à chaque changement important.', 'Le DUERP doit être tenu à la disposition des travailleurs.', 'Signaler un risque nouveau permet de mettre à jour l’évaluation des risques.', '{"type":"collection"}'::jsonb, 'obligation', '[{"label":"Code du travail, art. R4121-1 et R4121-2","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"INRS : Évaluation des risques professionnels","url":"https://www.inrs.fr/demarche/evaluation-risques-professionnels.html"}]'::jsonb, 'a-verifier', true),
  ('poste-ecran', 19, 'Poste de travail sur écran', 'postures', 'commune', 'Monitor', 'Un poste bien réglé limite la fatigue visuelle et les douleurs : haut de l’écran à hauteur des yeux ou légèrement en dessous, écran à environ une longueur de bras.', 'On place l’écran perpendiculairement aux fenêtres pour éviter les reflets et l’éblouissement. Les pieds reposent à plat, les avant-bras sont soutenus.', 'Avec deux écrans utilisés autant l’un que l’autre, on les place côte à côte, centrés face à soi.', 'Régler son siège d’abord, puis la hauteur et la distance de l’écran.', '{"type":"maitrise","seuil":1}'::jsonb, 'recommandation', '[{"label":"INRS : Travail sur écran","url":"https://www.inrs.fr/risques/travail-ecran.html"}]'::jsonb, 'a-verifier', true),
  ('varier-postures', 20, 'Varier ses postures', 'postures', 'commune', 'Repeat', 'Rester longtemps dans la même position sollicite toujours les mêmes muscles. Alterner les postures et faire de courtes pauses réduit les contraintes.', 'Se lever, marcher, changer de tâche : de petites variations régulières sont plus efficaces qu’une longue pause unique.', 'En ergonomie, on dit souvent que la meilleure posture est… la suivante.', 'Bouger régulièrement fait partie du travail bien fait.', '{"type":"maitrise","seuil":3}'::jsonb, 'recommandation', '[{"label":"INRS : Troubles musculosquelettiques","url":"https://www.inrs.fr/risques/tms-troubles-musculosquelettiques.html"}]'::jsonb, 'a-verifier', true),
  ('gestes-port-charge', 21, 'Porter une charge', 'postures', 'peu-commune', 'Package', 'Pour soulever une charge : se rapprocher, fléchir les jambes, garder le dos droit, tenir la charge près du corps et éviter de tourner le tronc.', 'Avant de porter, on évalue la charge (poids, prise, stabilité) et le trajet. Pour changer de direction, on pivote avec les pieds.', 'Plus la charge est éloignée du corps, plus l’effort supporté par le bas du dos augmente.', 'Si la charge est trop lourde ou encombrante, on demande de l’aide ou une aide mécanique.', '{"type":"maitrise","seuil":5}'::jsonb, 'recommandation', '[{"label":"INRS : Activité physique et manutention","url":"https://www.inrs.fr/risques/activite-physique.html"}]'::jsonb, 'a-verifier', true),
  ('limites-charge', 22, 'Limites de charge', 'postures', 'rare', 'Weight', 'Un homme ne peut être amené à porter de façon habituelle des charges de plus de 55 kg que s’il a été reconnu apte par le médecin du travail, et jamais plus de 105 kg.', 'Pour les femmes, le port de charges de plus de 25 kg est interdit (40 kg avec une brouette). Ces limites sont des maximums, pas des objectifs.', 'Des valeurs bien plus basses sont recommandées en prévention, car les TMS surviennent bien en dessous de ces limites.', 'Les limites légales ne garantissent pas l’absence de risque : on réduit le port de charges au maximum.', '{"type":"parcours","parcoursId":"p-postures"}'::jsonb, 'obligation', '[{"label":"Code du travail, art. R4541-9 et D4152-12","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"INRS : Activité physique et manutention","url":"https://www.inrs.fr/risques/activite-physique.html"}]'::jsonb, 'a-verifier', true),
  ('tms', 23, 'Troubles musculosquelettiques', 'postures', 'epique', 'Activity', 'Les TMS touchent muscles, tendons et nerfs (dos, épaules, poignets…). Ils constituent la première cause de maladies professionnelles reconnues en France.', 'Ils résultent de la combinaison de gestes répétitifs, d’efforts, de postures contraignantes, mais aussi du stress et de l’organisation du travail.', 'Douleurs, fourmillements ou raideurs qui reviennent sont des signaux d’alerte à signaler tôt.', 'En cas de douleurs persistantes, on en parle au médecin du travail sans attendre.', '{"type":"scenario","scenarioId":"s-postures"}'::jsonb, 'recommandation', '[{"label":"INRS : Troubles musculosquelettiques","url":"https://www.inrs.fr/risques/tms-troubles-musculosquelettiques.html"},{"label":"Assurance Maladie : Risques professionnels","url":"https://www.ameli.fr/entreprise/sante-travail"}]'::jsonb, 'a-verifier', true),
  ('manutention-assistee', 24, 'Manutention assistée', 'postures', 'legendaire', 'Forklift', 'L’employeur organise le travail et fournit des équipements, notamment mécaniques, pour éviter le recours à la manutention manuelle.', 'Diable, transpalette, chariot, table élévatrice : ces aides réduisent l’effort, à condition d’être formé à leur utilisation.', 'La conduite d’un chariot automoteur nécessite une autorisation de conduite délivrée par l’employeur.', 'Une aide mécanique disponible, c’est une aide à utiliser.', '{"type":"collection"}'::jsonb, 'obligation', '[{"label":"Code du travail, art. R4541-3","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"INRS : Activité physique et manutention","url":"https://www.inrs.fr/risques/activite-physique.html"}]'::jsonb, 'a-verifier', true),
  ('couleurs-signalisation', 25, 'Couleurs de signalisation', 'organisation', 'commune', 'Signpost', 'Rouge : interdiction et matériel incendie. Jaune : avertissement d’un danger. Bleu : obligation. Vert : sauvetage et premiers secours.', 'La forme compte aussi : cercle pour l’interdiction et l’obligation, triangle pour l’avertissement, carré ou rectangle pour l’information.', 'Les pictogrammes de sécurité sont harmonisés au niveau international par la norme ISO 7010.', 'Un panneau bleu rond signifie une obligation : par exemple, porter un casque.', '{"type":"maitrise","seuil":1}'::jsonb, 'obligation', '[{"label":"Arrêté du 4 novembre 1993 relatif à la signalisation de sécurité et de santé au travail"},{"label":"Norme ISO 7010"},{"label":"INRS : Signalisation de santé et de sécurité","url":"https://www.inrs.fr/demarche/signalisation-sante-securite.html"}]'::jsonb, 'a-verifier', true),
  ('numeros-urgence', 26, 'Numéros d’urgence', 'organisation', 'commune', 'PhoneCall', '15 : SAMU. 18 : sapeurs-pompiers. 112 : numéro d’urgence européen. 114 : numéro d’urgence pour les personnes sourdes ou malentendantes (SMS, visio).', 'Lors de l’appel, on précise : le lieu exact, la nature de l’accident, le nombre de victimes et leur état. On ne raccroche que lorsque l’opérateur l’indique.', 'Le 112 fonctionne dans tous les pays de l’Union européenne.', 'Connaître aussi le numéro d’urgence interne de son site et la procédure d’accueil des secours.', '{"type":"maitrise","seuil":3}'::jsonb, 'recommandation', '[{"label":"Service-Public.fr : Numéros d’urgence","url":"https://www.service-public.fr/particuliers/vosdroits/F33954"}]'::jsonb, 'a-verifier', true),
  ('proteger-alerter-secourir', 27, 'Protéger, alerter, secourir', 'organisation', 'peu-commune', 'HeartPulse', 'Face à un accident : protéger pour éviter un suraccident, alerter les secours, puis secourir la victime dans la limite de ses compétences.', 'Protéger, c’est supprimer le danger ou isoler la zone, sans se mettre soi-même en danger.', 'Cette démarche est au cœur de la formation de sauveteur secouriste du travail (SST).', 'On ne déplace pas une victime, sauf danger immédiat et impossible à supprimer.', '{"type":"maitrise","seuil":5}'::jsonb, 'recommandation', '[{"label":"INRS : Sauvetage secourisme du travail","url":"https://www.inrs.fr/demarche/sauvetage-secourisme-travail.html"}]'::jsonb, 'a-verifier', true),
  ('droit-alerte-retrait', 28, 'Droit d’alerte et de retrait', 'organisation', 'rare', 'Megaphone', 'Un travailleur alerte immédiatement l’employeur de toute situation dont il a un motif raisonnable de penser qu’elle présente un danger grave et imminent. Il peut se retirer de cette situation.', 'Le retrait ne doit pas créer une nouvelle situation de danger grave et imminent pour d’autres personnes.', 'Aucune sanction ni retenue de salaire ne peut être prise contre un travailleur qui s’est retiré d’une situation dont il avait un motif raisonnable de penser qu’elle présentait un danger grave et imminent.', 'Face à un danger grave et imminent : alerter d’abord, se retirer si nécessaire.', '{"type":"parcours","parcoursId":"p-organisation"}'::jsonb, 'obligation', '[{"label":"Code du travail, art. L4131-1 et L4131-3","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"}]'::jsonb, 'a-verifier', true),
  ('circulation', 29, 'Circulation dans les locaux', 'organisation', 'epique', 'Route', 'Les chutes de plain-pied et les collisions avec des engins sont des accidents fréquents. Allées balisées, sols dégagés et séparation piétons/engins les préviennent.', 'On emprunte les cheminements piétons, on tient la rampe dans les escaliers et on ne court pas, même pressé.', 'Les chutes de plain-pied (glissades, trébuchements) sont l’une des premières causes d’accidents du travail.', 'Un câble qui traîne ou un sol glissant se signale et se traite tout de suite.', '{"type":"scenario","scenarioId":"s-organisation"}'::jsonb, 'recommandation', '[{"label":"INRS : Chutes de plain-pied","url":"https://www.inrs.fr/risques/chutes-plain-pied.html"}]'::jsonb, 'a-verifier', true),
  ('sst', 30, 'Sauveteur secouriste du travail', 'organisation', 'legendaire', 'Cross', 'Dans chaque atelier où sont effectués des travaux dangereux, un membre du personnel doit avoir reçu la formation de secourisme nécessaire pour donner les premiers secours en cas d’urgence.', 'Le SST sait protéger, examiner la victime, faire alerter et secourir. Il contribue aussi à la prévention dans l’entreprise.', 'Le certificat SST doit être actualisé régulièrement par un maintien et actualisation des compétences (MAC).', 'Connaître les SST de son équipe et l’emplacement de la trousse de secours et du défibrillateur.', '{"type":"collection"}'::jsonb, 'obligation', '[{"label":"Code du travail, art. R4224-15","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"INRS : Sauvetage secourisme du travail","url":"https://www.inrs.fr/demarche/sauvetage-secourisme-travail.html"}]'::jsonb, 'a-verifier', true);
insert into public.questions (id, categorie, difficulte, enonce, choix, bonne_reponse, explication, nature, sources, verif_statut, publie) values
  ('inc-1', 'incendie', 1, 'Quels sont les trois éléments nécessaires à la naissance d’un feu ?', '[{"id":"a","texte":"Combustible, comburant, énergie d’activation"},{"id":"b","texte":"Chaleur, fumée, flamme"},{"id":"c","texte":"Oxygène, eau, électricité"},{"id":"d","texte":"Combustible, fumée, vent"}]'::jsonb, 'a', 'C’est le triangle du feu : un combustible (ce qui brûle), un comburant (en général l’oxygène de l’air) et une énergie d’activation (chaleur, étincelle). Supprimer l’un des trois éteint le feu.', 'recommandation', '[{"label":"INRS : Incendie et explosion","url":"https://www.inrs.fr/risques/incendie-explosion.html"}]'::jsonb, 'a-verifier', true),
  ('inc-2', 'incendie', 1, 'L’alarme incendie retentit pendant une réunion. Que faites-vous ?', '[{"id":"a","texte":"J’attends de savoir s’il s’agit d’un exercice"},{"id":"b","texte":"J’évacue immédiatement en suivant le balisage"},{"id":"c","texte":"Je termine mon appel puis je sors"},{"id":"d","texte":"Je vais vérifier d’où vient le feu"}]'::jsonb, 'b', 'Le signal d’alarme générale ordonne l’évacuation. Attendre une confirmation fait perdre un temps précieux : un exercice se traite comme une situation réelle.', 'recommandation', '[{"label":"INRS : Incendie et explosion","url":"https://www.inrs.fr/risques/incendie-explosion.html"}]'::jsonb, 'a-verifier', true),
  ('inc-3', 'incendie', 2, 'Un feu de friteuse (huile de cuisson) correspond à quelle classe de feu ?', '[{"id":"a","texte":"Classe A"},{"id":"b","texte":"Classe B"},{"id":"c","texte":"Classe D"},{"id":"d","texte":"Classe F"}]'::jsonb, 'd', 'La classe F concerne les feux d’huiles et de graisses de cuisson. Ne jamais y jeter d’eau : l’huile en feu est projetée violemment. On utilise un extincteur adapté à la classe F ou on étouffe le feu.', 'norme', '[{"label":"Norme NF EN 2"},{"label":"INRS : Incendie et explosion","url":"https://www.inrs.fr/risques/incendie-explosion.html"}]'::jsonb, 'a-verifier', true),
  ('inc-4', 'incendie', 2, 'Quel extincteur est généralement adapté à un feu d’origine électrique ?', '[{"id":"a","texte":"Extincteur à eau pulvérisée sans additif"},{"id":"b","texte":"Extincteur au CO2"},{"id":"c","texte":"Extincteur à mousse"},{"id":"d","texte":"Aucun extincteur"}]'::jsonb, 'b', 'Le CO2 n’est pas conducteur et ne laisse pas de résidu : il est adapté aux feux d’origine électrique. Toujours vérifier sur l’étiquette la mention d’utilisation sur équipements sous tension, et couper le courant si possible.', 'recommandation', '[{"label":"INRS : Incendie et explosion","url":"https://www.inrs.fr/risques/incendie-explosion.html"}]'::jsonb, 'a-verifier', true),
  ('inc-5', 'incendie', 2, 'Pourquoi faut-il tenir un extincteur CO2 par sa poignée et non par le diffuseur ?', '[{"id":"a","texte":"Le diffuseur est fragile"},{"id":"b","texte":"Le diffuseur devient extrêmement froid et peut brûler la main"},{"id":"c","texte":"Le diffuseur est sous tension"},{"id":"d","texte":"Pour viser plus haut"}]'::jsonb, 'b', 'La détente du CO2 refroidit fortement le diffuseur : le saisir à main nue peut provoquer des brûlures par le froid.', 'recommandation', '[{"label":"INRS : Incendie et explosion","url":"https://www.inrs.fr/risques/incendie-explosion.html"}]'::jsonb, 'a-verifier', true),
  ('inc-6', 'incendie', 3, 'À quelle fréquence minimale les exercices d’évacuation incendie doivent-ils avoir lieu ?', '[{"id":"a","texte":"Tous les mois"},{"id":"b","texte":"Tous les six mois"},{"id":"c","texte":"Tous les deux ans"},{"id":"d","texte":"Uniquement à l’embauche"}]'::jsonb, 'b', 'Le Code du travail prévoit des exercices et essais périodiques au moins tous les six mois. Ils permettent notamment d’apprendre à reconnaître l’alarme et à exécuter les manœuvres nécessaires.', 'obligation', '[{"label":"Code du travail, art. R4227-39","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"}]'::jsonb, 'a-verifier', true),
  ('epi-1', 'epi', 1, 'Que signifie le sigle EPI ?', '[{"id":"a","texte":"Équipement de prévention incendie"},{"id":"b","texte":"Équipement de protection individuelle"},{"id":"c","texte":"Évaluation des postes individuels"},{"id":"d","texte":"Équipe de première intervention"}]'::jsonb, 'b', 'Un EPI est un équipement porté par une personne pour la protéger d’un ou plusieurs risques : casque, gants, lunettes, chaussures, protections auditives, etc.', 'obligation', '[{"label":"INRS : Équipements de protection individuelle","url":"https://www.inrs.fr/demarche/equipements-protection-individuelle.html"}]'::jsonb, 'a-verifier', true),
  ('epi-2', 'epi', 1, 'Votre casque a subi un choc violent, mais ne présente aucune fissure visible. Que faites-vous ?', '[{"id":"a","texte":"Je continue à le porter"},{"id":"b","texte":"Je le remplace"},{"id":"c","texte":"Je le répare avec du ruban adhésif"},{"id":"d","texte":"Je le porte uniquement en intérieur"}]'::jsonb, 'b', 'Après un choc important, la coque peut être fragilisée sans que cela se voie. Le casque n’offre plus la protection garantie : il faut le remplacer.', 'recommandation', '[{"label":"INRS : Équipements de protection individuelle","url":"https://www.inrs.fr/demarche/equipements-protection-individuelle.html"}]'::jsonb, 'a-verifier', true),
  ('epi-3', 'epi', 2, 'À partir de quel niveau d’exposition quotidienne au bruit l’employeur doit-il veiller à ce que les protecteurs auditifs soient effectivement portés ?', '[{"id":"a","texte":"70 dB(A)"},{"id":"b","texte":"80 dB(A)"},{"id":"c","texte":"85 dB(A)"},{"id":"d","texte":"100 dB(A)"}]'::jsonb, 'c', 'À partir de 80 dB(A), les protecteurs sont mis à disposition. À partir de 85 dB(A), l’employeur veille à ce qu’ils soient portés. La valeur limite est de 87 dB(A).', 'obligation', '[{"label":"Code du travail, art. R4431-2 et R4434-7","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"INRS : Bruit","url":"https://www.inrs.fr/risques/bruit.html"}]'::jsonb, 'a-verifier', true),
  ('epi-4', 'epi', 2, 'Des lunettes de vue classiques protègent-elles contre les projections ?', '[{"id":"a","texte":"Oui, toujours"},{"id":"b","texte":"Oui, si les verres sont en plastique"},{"id":"c","texte":"Non, il faut une protection oculaire certifiée"},{"id":"d","texte":"Oui, si elles ont des branches larges"}]'::jsonb, 'c', 'Des lunettes de vue ne sont pas conçues pour résister aux impacts et ne protègent pas sur les côtés. Il existe des surlunettes et des lunettes de protection correctrices certifiées.', 'norme', '[{"label":"Norme EN 166"},{"label":"INRS : Équipements de protection individuelle","url":"https://www.inrs.fr/demarche/equipements-protection-individuelle.html"}]'::jsonb, 'a-verifier', true),
  ('epi-5', 'epi', 3, 'Vous travaillez près d’une perceuse à colonne en fonctionnement. Que dire du port de gants ?', '[{"id":"a","texte":"Les gants sont toujours obligatoires"},{"id":"b","texte":"Les gants peuvent augmenter le risque d’entraînement de la main"},{"id":"c","texte":"N’importe quel gant convient"},{"id":"d","texte":"Les gants en cuir suppriment tout risque"}]'::jsonb, 'b', 'Près de pièces en rotation, un gant peut être happé et entraîner la main. Les règles du poste précisent si le port de gants est proscrit.', 'recommandation', '[{"label":"INRS : Équipements de protection individuelle","url":"https://www.inrs.fr/demarche/equipements-protection-individuelle.html"},{"label":"INRS : Machines","url":"https://www.inrs.fr/risques/machines.html"}]'::jsonb, 'a-verifier', true),
  ('epi-6', 'epi', 3, 'Qui doit fournir et payer les EPI nécessaires au poste de travail ?', '[{"id":"a","texte":"Le salarié"},{"id":"b","texte":"L’employeur, gratuitement"},{"id":"c","texte":"Le salarié et l’employeur à parts égales"},{"id":"d","texte":"L’Assurance Maladie"}]'::jsonb, 'b', 'Les EPI sont fournis gratuitement par l’employeur, qui assure aussi leur bon fonctionnement et leur état hygiénique satisfaisant.', 'obligation', '[{"label":"Code du travail, art. R4323-95","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"}]'::jsonb, 'a-verifier', true),
  ('ris-1', 'risques', 1, 'Une prise électrique de votre atelier pend du mur, fils apparents. Que faites-vous ?', '[{"id":"a","texte":"Je la remets en place moi-même"},{"id":"b","texte":"Je la signale et j’empêche son utilisation"},{"id":"c","texte":"Je l’utilise avec précaution"},{"id":"d","texte":"Je coupe les fils apparents"}]'::jsonb, 'b', 'Les opérations sur les installations électriques sont réservées aux personnes habilitées. On signale le défaut et on empêche l’accès ou l’utilisation en attendant la réparation.', 'obligation', '[{"label":"Code du travail, art. R4544-9","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"INRS : Risques électriques","url":"https://www.inrs.fr/risques/electriques.html"}]'::jsonb, 'a-verifier', true),
  ('ris-2', 'risques', 1, 'Quelle est la forme des pictogrammes de danger des produits chimiques ?', '[{"id":"a","texte":"Un cercle bleu"},{"id":"b","texte":"Un triangle jaune"},{"id":"c","texte":"Un losange blanc bordé de rouge"},{"id":"d","texte":"Un carré vert"}]'::jsonb, 'c', 'Selon le règlement CLP, les pictogrammes de danger chimique sont des losanges à fond blanc bordés de rouge, avec un symbole noir.', 'obligation', '[{"label":"Règlement (CE) n° 1272/2008 (CLP)","url":"https://eur-lex.europa.eu/eli/reg/2008/1272/oj"},{"label":"INRS : Risques chimiques","url":"https://www.inrs.fr/risques/chimiques.html"}]'::jsonb, 'a-verifier', true),
  ('ris-3', 'risques', 2, 'Où trouver les équipements de protection recommandés pour manipuler un produit chimique ?', '[{"id":"a","texte":"Sur le site du fabricant uniquement"},{"id":"b","texte":"Dans la fiche de données de sécurité (FDS)"},{"id":"c","texte":"Sur la facture"},{"id":"d","texte":"Nulle part"}]'::jsonb, 'b', 'La fiche de données de sécurité comporte 16 rubriques. La rubrique 8 traite des contrôles de l’exposition et de la protection individuelle.', 'obligation', '[{"label":"Règlement (CE) n° 1907/2006 (REACH), art. 31","url":"https://eur-lex.europa.eu/eli/reg/2006/1907/oj"},{"label":"INRS : Risques chimiques","url":"https://www.inrs.fr/risques/chimiques.html"}]'::jsonb, 'a-verifier', true),
  ('ris-4', 'risques', 2, 'Vous devez récupérer un carton sur une étagère haute. Quelle solution est la plus sûre ?', '[{"id":"a","texte":"Monter sur une chaise à roulettes"},{"id":"b","texte":"Monter sur une chaise fixe"},{"id":"c","texte":"Utiliser un marchepied ou une plateforme adaptée"},{"id":"d","texte":"Grimper sur les étagères basses"}]'::jsonb, 'c', 'Les chaises, et plus encore les chaises à roulettes, sont instables. Un marchepied ou une plateforme conçus pour cet usage réduisent fortement le risque de chute.', 'recommandation', '[{"label":"INRS : Chutes de hauteur","url":"https://www.inrs.fr/risques/chutes-hauteur.html"}]'::jsonb, 'a-verifier', true),
  ('ris-5', 'risques', 3, 'Une machine est bloquée. Avant d’intervenir à l’intérieur, que faut-il faire ?', '[{"id":"a","texte":"L’arrêter avec le bouton d’arrêt suffit"},{"id":"b","texte":"Appliquer la procédure de consignation"},{"id":"c","texte":"Demander à un collègue de surveiller le bouton"},{"id":"d","texte":"Intervenir rapidement en gardant les mains loin"}]'::jsonb, 'b', 'Le bouton d’arrêt ne garantit pas l’absence d’énergie ni l’impossibilité d’un redémarrage. La consignation sépare les énergies, les condamne (cadenas) et vérifie leur absence.', 'recommandation', '[{"label":"INRS : Machines","url":"https://www.inrs.fr/risques/machines.html"}]'::jsonb, 'a-verifier', true),
  ('ris-6', 'risques', 3, 'Dans une entreprise d’au moins 11 salariés, à quelle fréquence minimale le document unique (DUERP) est-il mis à jour ?', '[{"id":"a","texte":"Tous les mois"},{"id":"b","texte":"Au moins chaque année"},{"id":"c","texte":"Tous les cinq ans"},{"id":"d","texte":"Jamais, il est établi une fois pour toutes"}]'::jsonb, 'b', 'Le DUERP est mis à jour au moins chaque année dans les entreprises d’au moins 11 salariés, ainsi que lors de toute décision d’aménagement important ou lorsqu’une information nouvelle sur un risque est recueillie.', 'obligation', '[{"label":"Code du travail, art. R4121-2","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"INRS : Évaluation des risques professionnels","url":"https://www.inrs.fr/demarche/evaluation-risques-professionnels.html"}]'::jsonb, 'a-verifier', true),
  ('pos-1', 'postures', 1, 'Où placer le haut de votre écran d’ordinateur ?', '[{"id":"a","texte":"Bien au-dessus des yeux"},{"id":"b","texte":"À hauteur des yeux ou légèrement en dessous"},{"id":"c","texte":"Au niveau du clavier"},{"id":"d","texte":"Peu importe"}]'::jsonb, 'b', 'Un écran trop haut fait relever la tête et contracte la nuque. Le haut de l’écran à hauteur des yeux, ou légèrement en dessous, permet une position de tête neutre.', 'recommandation', '[{"label":"INRS : Travail sur écran","url":"https://www.inrs.fr/risques/travail-ecran.html"}]'::jsonb, 'a-verifier', true),
  ('pos-2', 'postures', 1, 'Comment orienter un écran par rapport à une fenêtre ?', '[{"id":"a","texte":"Face à la fenêtre"},{"id":"b","texte":"Dos à la fenêtre"},{"id":"c","texte":"Perpendiculairement à la fenêtre"},{"id":"d","texte":"L’orientation n’a pas d’importance"}]'::jsonb, 'c', 'Face à la fenêtre, on est ébloui ; dos à la fenêtre, l’écran reflète la lumière. Perpendiculairement, on limite les deux.', 'recommandation', '[{"label":"INRS : Travail sur écran","url":"https://www.inrs.fr/risques/travail-ecran.html"}]'::jsonb, 'a-verifier', true),
  ('pos-3', 'postures', 2, 'En portant un carton, vous devez changer de direction. Comment faire ?', '[{"id":"a","texte":"Tourner le buste en gardant les pieds fixes"},{"id":"b","texte":"Pivoter avec les pieds"},{"id":"c","texte":"Lancer le carton"},{"id":"d","texte":"Se pencher en arrière"}]'::jsonb, 'b', 'La torsion du tronc en charge est particulièrement contraignante pour le dos. On déplace les pieds pour pivoter tout le corps.', 'recommandation', '[{"label":"INRS : Activité physique et manutention","url":"https://www.inrs.fr/risques/activite-physique.html"}]'::jsonb, 'a-verifier', true),
  ('pos-4', 'postures', 2, 'Quelle est la première cause de maladies professionnelles reconnues en France ?', '[{"id":"a","texte":"Les troubles musculosquelettiques (TMS)"},{"id":"b","texte":"Les allergies"},{"id":"c","texte":"Les pertes d’audition"},{"id":"d","texte":"Les brûlures"}]'::jsonb, 'a', 'Les TMS (dos, épaules, coudes, poignets) représentent la grande majorité des maladies professionnelles reconnues. Leur prévention passe par l’aménagement des postes et l’organisation du travail.', 'recommandation', '[{"label":"INRS : Troubles musculosquelettiques","url":"https://www.inrs.fr/risques/tms-troubles-musculosquelettiques.html"},{"label":"Assurance Maladie : Risques professionnels","url":"https://www.ameli.fr/entreprise/sante-travail"}]'::jsonb, 'a-verifier', true),
  ('pos-5', 'postures', 3, 'Au-delà de quel poids un homme ne peut-il porter habituellement une charge que s’il a été reconnu apte par le médecin du travail ?', '[{"id":"a","texte":"25 kg"},{"id":"b","texte":"40 kg"},{"id":"c","texte":"55 kg"},{"id":"d","texte":"105 kg"}]'::jsonb, 'c', 'Au-delà de 55 kg, un homme doit avoir été reconnu apte par le médecin du travail, et la charge ne peut jamais dépasser 105 kg. Ce sont des maximums : la prévention recommande des valeurs bien plus basses.', 'obligation', '[{"label":"Code du travail, art. R4541-9","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"}]'::jsonb, 'a-verifier', true),
  ('pos-6', 'postures', 3, 'Un transpalette est disponible pour déplacer des colis lourds. Que prévoit la réglementation ?', '[{"id":"a","texte":"Son usage est facultatif"},{"id":"b","texte":"L’employeur doit chercher à éviter la manutention manuelle, notamment par des aides mécaniques"},{"id":"c","texte":"Il est réservé aux charges de plus de 105 kg"},{"id":"d","texte":"Il est interdit en intérieur"}]'::jsonb, 'b', 'L’employeur prend les mesures d’organisation appropriées ou fournit les moyens adaptés, notamment mécaniques, pour éviter le recours à la manutention manuelle.', 'obligation', '[{"label":"Code du travail, art. R4541-3","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"}]'::jsonb, 'a-verifier', true),
  ('org-1', 'organisation', 1, 'Que signifie un panneau rond à fond bleu avec un pictogramme blanc ?', '[{"id":"a","texte":"Une interdiction"},{"id":"b","texte":"Un avertissement"},{"id":"c","texte":"Une obligation"},{"id":"d","texte":"Une issue de secours"}]'::jsonb, 'c', 'Rond et bleu : obligation (porter un casque, des lunettes…). Rond rouge barré : interdiction. Triangle jaune : avertissement. Vert : sauvetage et secours.', 'obligation', '[{"label":"Arrêté du 4 novembre 1993 relatif à la signalisation de sécurité et de santé au travail"},{"label":"INRS : Signalisation de santé et de sécurité","url":"https://www.inrs.fr/demarche/signalisation-sante-securite.html"}]'::jsonb, 'a-verifier', true),
  ('org-2', 'organisation', 1, 'Quel numéro d’urgence fonctionne dans tous les pays de l’Union européenne ?', '[{"id":"a","texte":"15"},{"id":"b","texte":"17"},{"id":"c","texte":"112"},{"id":"d","texte":"114"}]'::jsonb, 'c', 'Le 112 est le numéro d’urgence européen. En France, le 15 joint le SAMU, le 18 les sapeurs-pompiers et le 114 est accessible par SMS aux personnes sourdes ou malentendantes.', 'recommandation', '[{"label":"Service-Public.fr : Numéros d’urgence","url":"https://www.service-public.fr/particuliers/vosdroits/F33954"}]'::jsonb, 'a-verifier', true),
  ('org-3', 'organisation', 2, 'Face à un accident, quel est le bon ordre d’action ?', '[{"id":"a","texte":"Secourir, alerter, protéger"},{"id":"b","texte":"Alerter, secourir, protéger"},{"id":"c","texte":"Protéger, alerter, secourir"},{"id":"d","texte":"Protéger, secourir, alerter"}]'::jsonb, 'c', 'On protège d’abord pour éviter un suraccident (y compris pour soi), on alerte les secours, puis on secourt la victime dans la limite de ses compétences.', 'recommandation', '[{"label":"INRS : Sauvetage secourisme du travail","url":"https://www.inrs.fr/demarche/sauvetage-secourisme-travail.html"}]'::jsonb, 'a-verifier', true),
  ('org-4', 'organisation', 2, 'Vous avez failli glisser sur une flaque d’huile dans une allée, sans vous blesser. Que faites-vous ?', '[{"id":"a","texte":"Rien, puisqu’il n’y a pas eu d’accident"},{"id":"b","texte":"Je signale la situation et je fais baliser la zone"},{"id":"c","texte":"J’attends que quelqu’un d’autre la signale"},{"id":"d","texte":"Je recouvre la flaque avec un carton"}]'::jsonb, 'b', 'Un presque-accident est un signal précieux : le signaler permet de traiter la cause avant qu’un accident ne se produise.', 'pratique-interne', '[{"label":"INRS : Chutes de plain-pied","url":"https://www.inrs.fr/risques/chutes-plain-pied.html"}]'::jsonb, 'a-verifier', true),
  ('org-5', 'organisation', 3, 'Un travailleur a un motif raisonnable de penser qu’une situation présente un danger grave et imminent pour sa vie. Que peut-il faire ?', '[{"id":"a","texte":"Rien sans l’accord écrit de son responsable"},{"id":"b","texte":"Alerter l’employeur et se retirer de la situation"},{"id":"c","texte":"Se retirer, à condition de poser un jour de congé"},{"id":"d","texte":"Uniquement alerter les pompiers"}]'::jsonb, 'b', 'C’est le droit d’alerte et de retrait. Aucune sanction ni retenue de salaire ne peut être prise si le motif était raisonnable. Le retrait ne doit pas créer de danger pour autrui.', 'obligation', '[{"label":"Code du travail, art. L4131-1 et L4131-3","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"}]'::jsonb, 'a-verifier', true),
  ('org-6', 'organisation', 3, 'Dans un atelier où sont réalisés des travaux dangereux, que prévoit le Code du travail en matière de premiers secours ?', '[{"id":"a","texte":"Rien de particulier"},{"id":"b","texte":"Qu’un membre du personnel ait reçu la formation de secourisme nécessaire"},{"id":"c","texte":"La présence permanente d’un médecin"},{"id":"d","texte":"Une infirmerie dans chaque atelier"}]'::jsonb, 'b', 'Un membre du personnel doit avoir reçu la formation de secourisme nécessaire pour donner les premiers secours en cas d’urgence. La formation SST répond à ce besoin.', 'obligation', '[{"label":"Code du travail, art. R4224-15","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"},{"label":"INRS : Sauvetage secourisme du travail","url":"https://www.inrs.fr/demarche/sauvetage-secourisme-travail.html"}]'::jsonb, 'a-verifier', true);
insert into public.scenarios (id, categorie, titre, accroche, lieu, etapes, nature, sources, verif_statut, publie) values
  ('s-incendie', 'incendie', 'Odeur de brûlé à l’atelier', 'Une odeur suspecte, puis de la fumée. Chaque seconde compte.', 'Atelier de maintenance, 14 h 10', '[{"id":"e1","situation":"Tu remarques une odeur de brûlé dans l’atelier. En t’approchant, tu vois une légère fumée s’échapper d’une armoire électrique. Que fais-tu en premier ?","options":[{"id":"a","texte":"J’ouvre l’armoire pour voir d’où vient le problème","correct":false,"consequence":"Ouvrir l’armoire apporte de l’oxygène et t’expose à un risque électrique. Seule une personne habilitée peut intervenir."},{"id":"b","texte":"Je donne l’alerte selon la consigne du site","correct":true,"consequence":"Bon réflexe : alerter tôt permet de mobiliser les bonnes personnes et, si besoin, de déclencher l’évacuation."},{"id":"c","texte":"Je termine ma tâche, ce n’est sans doute rien","correct":false,"consequence":"Un début de feu se développe très vite. Une fumée inhabituelle doit toujours être signalée immédiatement."}]},{"id":"e2","situation":"Des flammes apparaissent sur le côté de l’armoire. Un extincteur CO2 et un extincteur à eau pulvérisée sans additif sont à proximité. Tu as été formé à leur utilisation.","options":[{"id":"a","texte":"J’utilise l’extincteur à eau","correct":false,"consequence":"L’eau sans additif adaptée est conductrice : sur un équipement électrique, risque d’électrisation."},{"id":"b","texte":"J’utilise l’extincteur CO2, en le tenant par la poignée","correct":true,"consequence":"Le CO2 est adapté aux feux d’origine électrique. Tenir la poignée évite les brûlures par le froid au diffuseur."},{"id":"c","texte":"Je jette un seau d’eau","correct":false,"consequence":"Danger : l’eau projetée sur un équipement sous tension expose à l’électrisation."}]},{"id":"e3","situation":"Le feu ne faiblit pas et l’alarme générale retentit. Comment évacues-tu ?","options":[{"id":"a","texte":"Je prends l’ascenseur, c’est plus rapide","correct":false,"consequence":"Les ascenseurs peuvent tomber en panne ou mener à un étage enfumé. On emprunte toujours les escaliers."},{"id":"b","texte":"Je suis le balisage, je ferme les portes derrière moi et je rejoins le point de rassemblement","correct":true,"consequence":"Exactement. Fermer les portes ralentit la propagation des fumées. Au point de rassemblement, tu te signales."},{"id":"c","texte":"Je retourne chercher mon sac au vestiaire","correct":false,"consequence":"On ne revient jamais en arrière pour récupérer des affaires : la situation peut se dégrader en quelques secondes."}]}]'::jsonb, 'recommandation', '[{"label":"INRS : Incendie et explosion","url":"https://www.inrs.fr/risques/incendie-explosion.html"},{"label":"Code du travail, art. R4227-37 à R4227-39","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"}]'::jsonb, 'a-verifier', true),
  ('s-epi', 'epi', 'Premier jour sur le quai', 'Un nouveau poste, de nouveaux risques. Es-tu bien équipé ?', 'Quai de chargement, 7 h 30', '[{"id":"e1","situation":"Tu arrives sur le quai de chargement. Des panneaux bleus indiquent le port obligatoire des chaussures de sécurité et du gilet haute visibilité. Tu as oublié tes chaussures.","options":[{"id":"a","texte":"Je travaille en baskets, en faisant attention","correct":false,"consequence":"Un colis qui tombe ou une roue de transpalette peut écraser le pied. Le panneau bleu signale une obligation."},{"id":"b","texte":"Je préviens mon responsable pour obtenir une paire avant de commencer","correct":true,"consequence":"Les EPI sont fournis par l’employeur. Mieux vaut quelques minutes de retard qu’un pied écrasé."},{"id":"c","texte":"J’emprunte une paire trop grande dans un vestiaire","correct":false,"consequence":"Des chaussures inadaptées à ta taille protègent mal et augmentent le risque de chute."}]},{"id":"e2","situation":"Un collègue te propose d’utiliser ses gants de manutention pour transvaser un produit corrosif.","options":[{"id":"a","texte":"J’accepte, des gants restent des gants","correct":false,"consequence":"Un gant de manutention ne protège pas contre les produits chimiques. Le produit peut traverser la matière."},{"id":"b","texte":"Je consulte la FDS du produit pour connaître les gants adaptés","correct":true,"consequence":"La fiche de données de sécurité indique les protections adaptées. Le gant doit correspondre au risque."},{"id":"c","texte":"Je travaille sans gants, mais vite","correct":false,"consequence":"Un produit corrosif peut causer des lésions graves en quelques secondes."}]},{"id":"e3","situation":"En fin de journée, tu remarques que la semelle d’une de tes chaussures de sécurité est fendue.","options":[{"id":"a","texte":"Je signale le défaut pour la faire remplacer","correct":true,"consequence":"Un EPI endommagé ne garantit plus la protection prévue. Le signaler permet son remplacement."},{"id":"b","texte":"Je la garde jusqu’à ce qu’elle soit complètement usée","correct":false,"consequence":"Une semelle fendue peut laisser passer un objet pointu ou provoquer une glissade."},{"id":"c","texte":"Je la répare avec de la colle forte","correct":false,"consequence":"Une réparation de fortune ne restaure pas les performances certifiées de la chaussure."}]}]'::jsonb, 'recommandation', '[{"label":"INRS : Équipements de protection individuelle","url":"https://www.inrs.fr/demarche/equipements-protection-individuelle.html"},{"label":"Code du travail, art. R4323-95","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"}]'::jsonb, 'a-verifier', true),
  ('s-risques', 'risques', 'La machine bloquée', 'La production attend. La tentation d’aller vite est forte.', 'Ligne de conditionnement, 10 h 45', '[{"id":"e1","situation":"Un carton s’est coincé dans la convoyeuse. Le chef d’équipe est occupé. Que fais-tu ?","options":[{"id":"a","texte":"Je passe la main sous le protecteur pour dégager le carton","correct":false,"consequence":"La machine peut redémarrer ou un élément bouger : risque grave d’écrasement ou d’amputation."},{"id":"b","texte":"J’arrête la machine et j’applique la procédure de consignation prévue","correct":true,"consequence":"La consignation (séparer, condamner, vérifier) empêche tout redémarrage pendant l’intervention."},{"id":"c","texte":"Je démonte le protecteur pour gagner du temps","correct":false,"consequence":"On ne neutralise jamais un protecteur : c’est lui qui sépare la main des pièces dangereuses."}]},{"id":"e2","situation":"Pendant ton intervention, un collègue veut remettre la ligne en marche. Ton cadenas est posé sur le sectionneur.","options":[{"id":"a","texte":"Je lui confie la clé de mon cadenas","correct":false,"consequence":"Le cadenas est personnel : toi seul dois pouvoir le retirer une fois en sécurité."},{"id":"b","texte":"Je lui explique que je suis dans la machine et que je retirerai mon cadenas à la fin","correct":true,"consequence":"C’est le principe de la condamnation : chaque intervenant pose et retire lui-même son cadenas."},{"id":"c","texte":"Je sors en vitesse pour ne pas le retarder","correct":false,"consequence":"Se précipiter fait oublier des outils ou des étapes. La remise en service suit aussi une procédure."}]}]'::jsonb, 'recommandation', '[{"label":"INRS : Machines","url":"https://www.inrs.fr/risques/machines.html"}]'::jsonb, 'a-verifier', true),
  ('s-postures', 'postures', 'Le déménagement du service', 'Des cartons, des écrans et une journée chargée.', 'Plateau administratif, 9 h 00', '[{"id":"e1","situation":"Ton service déménage. Un carton d’archives très lourd est posé au sol. Un diable est disponible au fond du couloir.","options":[{"id":"a","texte":"Je le soulève d’un coup, dos penché","correct":false,"consequence":"Soulever dos penché, charge éloignée du corps, sollicite fortement les disques lombaires."},{"id":"b","texte":"Je vais chercher le diable","correct":true,"consequence":"L’aide mécanique supprime l’essentiel de l’effort. Elle doit être privilégiée dès qu’elle existe."},{"id":"c","texte":"Je le pousse du pied jusqu’au bureau","correct":false,"consequence":"Pousser avec le pied déséquilibre et peut provoquer une chute ou une entorse."}]},{"id":"e2","situation":"Tu installes ton nouveau poste. L’écran est posé sur une pile de ramettes, nettement au-dessus de tes yeux.","options":[{"id":"a","texte":"Je le garde ainsi, je m’y habituerai","correct":false,"consequence":"Lever la tête toute la journée contracte la nuque et les épaules : un facteur de TMS."},{"id":"b","texte":"Je règle mon siège puis j’abaisse l’écran à hauteur des yeux, à une longueur de bras","correct":true,"consequence":"On règle d’abord le siège, puis l’écran : tête droite, épaules relâchées."},{"id":"c","texte":"Je rapproche l’écran à 20 cm","correct":false,"consequence":"Un écran trop proche fatigue les yeux. La distance recommandée est d’environ une longueur de bras."}]},{"id":"e3","situation":"Depuis quelques semaines, tu ressens des fourmillements dans le poignet en fin de journée.","options":[{"id":"a","texte":"J’attends que ça passe tout seul","correct":false,"consequence":"Les TMS s’aggravent souvent s’ils ne sont pas pris en charge tôt."},{"id":"b","texte":"J’en parle au médecin du travail et à mon responsable","correct":true,"consequence":"Signaler tôt permet d’adapter le poste et d’éviter que le trouble ne devienne chronique."},{"id":"c","texte":"Je prends des antidouleurs pour continuer","correct":false,"consequence":"Masquer la douleur ne traite pas la cause et peut aggraver la lésion."}]}]'::jsonb, 'recommandation', '[{"label":"INRS : Activité physique et manutention","url":"https://www.inrs.fr/risques/activite-physique.html"},{"label":"INRS : Troubles musculosquelettiques","url":"https://www.inrs.fr/risques/tms-troubles-musculosquelettiques.html"},{"label":"Code du travail, art. R4541-3","url":"https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072050/"}]'::jsonb, 'a-verifier', true),
  ('s-organisation', 'organisation', 'Chute dans l’escalier', 'Un collègue est au sol. Les bons gestes, dans le bon ordre.', 'Escalier du bâtiment B, 16 h 20', '[{"id":"e1","situation":"Tu trouves un collègue allongé en bas de l’escalier, conscient mais incapable de se relever. Une flaque de liquide se trouve sur les marches.","options":[{"id":"a","texte":"Je l’aide immédiatement à se relever","correct":false,"consequence":"Mobiliser une victime peut aggraver une blessure, notamment au dos ou au cou."},{"id":"b","texte":"Je balise la flaque pour éviter qu’un autre ne chute, sans m’exposer","correct":true,"consequence":"Protéger d’abord : éviter le suraccident, pour la victime, pour les autres et pour soi."},{"id":"c","texte":"Je descends en courant le rejoindre","correct":false,"consequence":"Courir sur des marches mouillées, c’est risquer de devenir la deuxième victime."}]},{"id":"e2","situation":"La zone est sécurisée. Qui contactes-tu ?","options":[{"id":"a","texte":"Le SST de l’étage et les secours selon la procédure interne","correct":true,"consequence":"Alerter rapidement les bonnes personnes : le SST peut agir en attendant les secours, que l’on appelle selon la consigne du site."},{"id":"b","texte":"Personne, je vais d’abord voir s’il va mieux dans une heure","correct":false,"consequence":"Retarder l’alerte peut avoir des conséquences graves si la blessure est sérieuse."},{"id":"c","texte":"Je publie un message dans le groupe de l’équipe","correct":false,"consequence":"Un message de groupe n’est pas une alerte : rien ne garantit qu’il sera lu à temps."}]},{"id":"e3","situation":"Le lendemain, tu remarques que la flaque provenait d’une fuite de la fontaine à eau du palier.","options":[{"id":"a","texte":"Je signale la fuite pour qu’elle soit réparée","correct":true,"consequence":"Traiter la cause évite qu’un nouvel accident se produise : c’est tout l’intérêt du signalement."},{"id":"b","texte":"Je n’en parle pas, l’accident a déjà eu lieu","correct":false,"consequence":"La cause est toujours présente : un autre accident peut se produire."},{"id":"c","texte":"Je pose une serpillière en permanence","correct":false,"consequence":"Une solution de fortune peut elle-même faire trébucher. Il faut traiter la cause."}]}]'::jsonb, 'recommandation', '[{"label":"INRS : Sauvetage secourisme du travail","url":"https://www.inrs.fr/demarche/sauvetage-secourisme-travail.html"},{"label":"Service-Public.fr : Numéros d’urgence","url":"https://www.service-public.fr/particuliers/vosdroits/F33954"},{"label":"INRS : Chutes de plain-pied","url":"https://www.inrs.fr/risques/chutes-plain-pied.html"}]'::jsonb, 'a-verifier', true);
insert into public.parcours (id, categorie, titre, description, question_ids, seuil, publie) values
  ('p-incendie', 'incendie', 'Les bases de la sécurité incendie', 'Triangle du feu, classes de feu, extincteurs et évacuation.', array['inc-1', 'inc-2', 'inc-3', 'inc-4', 'inc-5', 'inc-6']::text[], 0.8, true),
  ('p-epi', 'epi', 'Identifier les équipements de protection', 'Choisir, porter et entretenir les bons EPI.', array['epi-1', 'epi-2', 'epi-3', 'epi-4', 'epi-5', 'epi-6']::text[], 0.8, true),
  ('p-risques', 'risques', 'Maîtriser les risques du quotidien', 'Électricité, produits chimiques, chutes et machines.', array['ris-1', 'ris-2', 'ris-3', 'ris-4', 'ris-5', 'ris-6']::text[], 0.8, true),
  ('p-postures', 'postures', 'Prévenir les accidents de manutention', 'Bons gestes, poste de travail et limites de charge.', array['pos-1', 'pos-2', 'pos-3', 'pos-4', 'pos-5', 'pos-6']::text[], 0.8, true),
  ('p-organisation', 'organisation', 'Réagir face à l’imprévu', 'Signalisation, alerte, premiers secours et droit de retrait.', array['org-1', 'org-2', 'org-3', 'org-4', 'org-5', 'org-6']::text[], 0.8, true);
